import { Keys } from "../Constants/Keys";
import { PageTitles } from "../Constants/PageTitles";
import { elements } from "../Elements/Elements";
export async function ActivateDemoMode() {
    const module = await import("../Datasets/DemoData");
    if (elements.demoDataSelector.value === "Demo_1") {
        localStorage.setItem(Keys.USER_CONFIGURATION, JSON.stringify(module.DEMO_DATA));
        localStorage.setItem(Keys.DEMO_DATA, "demo1");
    }
    else if (elements.demoDataSelector.value === "Demo_2") {
        localStorage.setItem(Keys.USER_CONFIGURATION, JSON.stringify(module.DEMO_DATA_2));
        localStorage.setItem(Keys.DEMO_DATA, "demo2");
    }
    location.reload();
}
export function NotifyDemoMode() {
    if (document.title === PageTitles.TABLE) {
        elements.demoDataButton.style.color = "#198754";
        elements.demoDataButton.disabled = true;
        elements.demoDataSelector.disabled = true;
    }
}
