import $ from "jquery";
import { ReversedTraceHeaderMap } from "../Constants/TraceHeaders";
export function GetSelectedRows() {
    const headers = Array.from(document.querySelectorAll(".thead-dark th")).map((header) => {
        return header.textContent;
    });
    const traceData = Array.from(document.querySelectorAll(".row-selected-problems")).map((row) => {
        return Array.from(row.querySelectorAll("td")).reduce((obj, cell, j) => {
            obj[headers[j] ?? ""] = cell.textContent ?? "";
            return obj;
        }, {});
    });
    return traceData;
}
export function GetFilteredRows() {
    function RemapObjectProperties(objects) {
        return objects.map((obj) => {
            const remappedObj = {};
            for (const key in obj) {
                const newKey = key in ReversedTraceHeaderMap
                    ? ReversedTraceHeaderMap[key]
                    : key;
                remappedObj[newKey] = obj[key];
            }
            return remappedObj;
        });
    }
    const table = $("#dataTableGenerated").DataTable();
    const data = table.rows({ search: "applied" }).data().toArray();
    const headers = table
        .columns()
        .header()
        .toArray()
        .map((header) => $(header).text());
    const objects = data.map((row) => {
        return headers.reduce((obj, header, index) => {
            obj[header] = row[index];
            return obj;
        }, {});
    });
    return RemapObjectProperties(objects);
}
