import { CalculateDirection, CalculatePrimalBound, CalculateDualBound, SetModelStatus, SetSolverStatus, CalculateGap, SetFailValueAndReason } from "./ResultComputations/ComputeResults";
export function AddResultCategories(traceData) {
    for (const obj of traceData) {
        obj["Direction"] = CalculateDirection(obj["Direction"]);
        obj["PrimalBoundSolver"] = CalculatePrimalBound(obj["ObjectiveValue"], obj["Direction"]);
        obj["DualBoundSolver"] = CalculateDualBound(obj["ObjectiveValueEstimate"], obj["Direction"]);
        obj["ModelStatus"] = SetModelStatus(obj["ModelStatus"]);
        obj["SolverStatus"] = SetSolverStatus(obj["SolverStatus"]);
        if (!("PrimalBoundProblem" in obj) || !obj["PrimalBoundProblem"]) {
            obj["PrimalBoundProblem"] = CalculatePrimalBound(obj["PrimalBoundSolver"], obj["Direction"]);
        }
        if (!("DualBoundProblem" in obj) || !obj["DualBoundProblem"]) {
            obj["DualBoundProblem"] = CalculateDualBound(obj["DualBoundSolver"], obj["Direction"]);
        }
        obj["Gap_Solver"] = CalculateGap(obj["PrimalBoundSolver"], obj["DualBoundSolver"], obj["Direction"]);
        obj["Gap_Problem"] = CalculateGap(obj["PrimalBoundProblem"], obj["DualBoundProblem"], obj["Direction"]);
        obj["PrimalGap"] = CalculateGap(obj["PrimalBoundSolver"], obj["PrimalBoundProblem"], obj["Direction"]);
        obj["DualGap"] = CalculateGap(obj["DualBoundSolver"], obj["DualBoundProblem"], obj["Direction"]);
        const [failValue, failReason] = SetFailValueAndReason(obj["SolverStatus"], obj["Direction"], obj["PrimalBoundSolver"], obj["DualBoundSolver"], obj["PrimalBoundProblem"], obj["DualBoundProblem"]);
        obj["Fail"] = failValue;
        obj["FailReason"] = failReason;
    }
}
