import Chart from "chart.js/auto";
import zoomPlugin from "chartjs-plugin-zoom";
import annotationPlugin from "chartjs-plugin-annotation";
import { elements } from "../Elements/Elements";
import { ShowPWANotification } from "../PWA/PWA-utils";
import { ChartMessages } from "../Constants/Messages";
let myChart = null;
Chart.register(zoomPlugin);
Chart.register(annotationPlugin);
export function PickColor(numberOfColors) {
    const colors = [];
    for (let i = 0; i < numberOfColors; i++) {
        const hex = Math.floor(Math.random() * 16777215).toString(16);
        const color = "#" + hex;
        colors.push(color);
    }
    return colors;
}
export function CreateChart(type, data, label, title, scaleOptions, zoomOptions, annotationOptions, subtitle) {
    if (myChart) {
        myChart.destroy();
    }
    myChart = new Chart(elements.chartCanvas, {
        type: type,
        data: {
            labels: typeof label === "string" ? [label] : label,
            datasets: data
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: scaleOptions || undefined,
            transitions: {
                zoom: {
                    animation: {
                        duration: 1000,
                        easing: "easeOutCubic"
                    }
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: title,
                    font: {
                        size: 20,
                        family: `system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue","Noto Sans","Liberation Sans",Arial,sans-serif,"Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol","Noto Color Emoji"`
                    }
                },
                subtitle: {
                    display: subtitle ? true : false,
                    text: subtitle || undefined
                },
                zoom: zoomOptions || undefined,
                annotation: annotationOptions || undefined
            }
        }
    });
    ShowPWANotification(ChartMessages.CHART_SUCCESS_HEADER, {
        body: ChartMessages.CHART_SUCCESS,
        icon: "../CSS/tab_icon.png",
        silent: true
    });
}
