function CreateInitialState() {
    return {
        dataFileType: "",
        defaultTime: undefined,
        gapLimit: undefined,
        unprocessedData: [],
        unprocessedInstanceInformationData: [],
        unprocessedSolutionData: [],
        chartData: []
    };
}
export const state = CreateInitialState();
export function ApplyStoredConfiguration(config) {
    state.unprocessedData = config.dataSet;
    state.dataFileType = config.dataFileType;
    state.defaultTime = config.defaultTime;
    state.gapLimit = config.gapLimit;
}
export function ResetAppState() {
    Object.assign(state, CreateInitialState());
}
