import { CalculateGap } from "./ComputeResults";
export function ComputeVirtualTimesTraceData(traceData, defaultTime) {
    const groupedByProblem = traceData.reduce((acc, item) => {
        const fileName = item["InputFileName"];
        acc[fileName] = acc[fileName] || [];
        const solverTime = isNaN(Number(item["SolverTime"])) || item["SolverTime"] === undefined
            ? defaultTime
            : item["SolverTime"];
        acc[fileName].push({ ...item, SolverTime: solverTime });
        return acc;
    }, {});
    const noFailedResults = Object.entries(groupedByProblem).reduce((acc, [key, items]) => {
        const filteredItems = items.filter((item) => item["Fail"] != null && item["Fail"].toString() === "false");
        if (filteredItems.length > 0) {
            acc[key] = filteredItems;
        }
        return acc;
    }, {});
    const result = [];
    Object.keys(noFailedResults).forEach((fileName) => {
        const times = noFailedResults[fileName].map((item) => item["SolverTime"]);
        const bestTime = Math.min(...times);
        let worstTime = Math.max(...times);
        if (worstTime > defaultTime) {
            worstTime = defaultTime;
        }
        const solverIterations = noFailedResults[fileName].map((item) => item["NumberOfIterations"]);
        const bestIterations = Math.min(...solverIterations);
        const worstIterations = Math.max(...solverIterations);
        const solverNodes = noFailedResults[fileName].map((item) => item["NumberOfNodes"]);
        const bestNodes = Math.min(...solverNodes);
        const worstNodes = Math.max(...solverNodes);
        const solverDomainViolations = noFailedResults[fileName].map((item) => item["NumberOfDomainViolations"]);
        const bestDomainViolations = Math.min(...solverDomainViolations);
        const worstDomainViolations = Math.max(...solverDomainViolations);
        const dualBoundSolver = noFailedResults[fileName].map((item) => Number(item["DualBoundSolver"]));
        const primalBoundSolver = noFailedResults[fileName].map((item) => Number(item["PrimalBoundSolver"]));
        let bestDualboundSolver, bestPrimalBoundSolver;
        let worstDualboundSolver, worstPrimalBoundSolver;
        const direction = noFailedResults[fileName][0].Direction;
        if (direction === "min") {
            bestDualboundSolver = Math.max(...dualBoundSolver);
            bestPrimalBoundSolver = Math.min(...primalBoundSolver);
            worstDualboundSolver = Math.min(...dualBoundSolver);
            worstPrimalBoundSolver = Math.max(...primalBoundSolver);
        }
        else {
            bestDualboundSolver = Math.min(...dualBoundSolver);
            bestPrimalBoundSolver = Math.max(...primalBoundSolver);
            worstDualboundSolver = Math.max(...dualBoundSolver);
            worstPrimalBoundSolver = Math.min(...primalBoundSolver);
        }
        const dualBoundProblem = Number(noFailedResults[fileName][0].DualBoundProblem);
        const primalBoundProblem = Number(noFailedResults[fileName][0].PrimalBoundProblem);
        const bestDualGap = CalculateGap(bestDualboundSolver, dualBoundProblem, direction);
        const worstDualGap = CalculateGap(worstDualboundSolver, dualBoundProblem, direction);
        const bestPrimalGap = CalculateGap(bestPrimalBoundSolver, primalBoundProblem, direction);
        const worstPrimalGap = CalculateGap(worstPrimalBoundSolver, primalBoundProblem, direction);
        const bestSolverGap = CalculateGap(bestPrimalBoundSolver, worstDualboundSolver, direction);
        const worstSolverGap = CalculateGap(worstPrimalBoundSolver, worstDualboundSolver, direction);
        result.push({
            InputFileName: fileName,
            Direction: direction,
            SolverName: "Virtual Best Solver",
            SolverTime: bestTime,
            PrimalGap: bestPrimalGap,
            DualGap: bestDualGap,
            Gap_Solver: bestSolverGap,
            SolverStatus: "Normal Completion",
            NumberOfDomainViolations: bestDomainViolations,
            NumberOfNodes: bestNodes,
            NumberOfIterations: bestIterations
        });
        result.push({
            InputFileName: fileName,
            Direction: direction,
            SolverName: "Virtual Worst Solver",
            SolverTime: worstTime,
            PrimalGap: worstPrimalGap,
            DualGap: worstDualGap,
            Gap_Solver: worstSolverGap,
            SolverStatus: "Normal Completion",
            NumberOfDomainViolations: worstDomainViolations,
            NumberOfNodes: worstNodes,
            NumberOfIterations: worstIterations
        });
    });
    return result;
}
export function ComputeVirtualTimes(data) {
    const bestWorst = { "Virtual Best Solver": [], "Virtual Worst Solver": [] };
    const bestEntries = {};
    const worstEntries = {};
    for (const group of Object.values(data)) {
        for (const entry of group) {
            const { time } = entry;
            const fileName = entry.InputFileName;
            if (!bestEntries[fileName] || time < bestEntries[fileName].time) {
                bestEntries[fileName] = { time, InputFileName: fileName };
            }
            if (!worstEntries[fileName] || time > worstEntries[fileName].time) {
                worstEntries[fileName] = { time, InputFileName: fileName };
            }
        }
    }
    for (const [, record] of Object.entries(bestEntries)) {
        bestWorst["Virtual Best Solver"].push(record);
    }
    for (const [, record] of Object.entries(worstEntries)) {
        bestWorst["Virtual Worst Solver"].push(record);
    }
    return bestWorst;
}
