import * as math from "mathjs";
import { Values } from "../../Constants/Values";
export function CalculateDirection(direction) {
    direction = 1 - 2 * Number(direction);
    if (direction === -1) {
        direction = "max";
        return direction;
    }
    else {
        direction = "min";
        return direction;
    }
}
export function CalculatePrimalBound(primalBound, direction) {
    if (typeof primalBound === "string") {
        switch (primalBound.toLowerCase()) {
            case "":
            case "na":
            case "nan":
            case "-nan":
                primalBound = direction === "max" ? -Infinity : Infinity;
                break;
            case "inf":
            case "+inf":
                primalBound = Infinity;
                break;
            case "-inf":
                primalBound = -Infinity;
                break;
            default:
                primalBound = Number(primalBound);
        }
    }
    return primalBound.toExponential(6);
}
export function CalculateDualBound(dualBound, direction) {
    if (typeof dualBound === "string") {
        switch (dualBound.toLowerCase()) {
            case "":
            case "na":
            case "nan":
            case "-nan":
                dualBound = direction === "max" ? Infinity : -Infinity;
                break;
            case "inf":
            case "+inf":
                dualBound = Infinity;
                break;
            case "-inf":
                dualBound = -Infinity;
                break;
            default:
                dualBound = Number(dualBound);
        }
    }
    return dualBound.toExponential(6);
}
export function CalculateGap(a, b, dir, tol = Values.TOLERANCE_LEVEL) {
    function AreValuesEffectivelyEqual(a, b, tol) {
        return Math.abs(a - b) < tol;
    }
    function IsGapCalculationNotApplicable(a, b, tol) {
        return (isNaN(a) ||
            isNaN(b) ||
            Math.min(Math.abs(a), Math.abs(b)) < tol ||
            (a === Infinity && b === Infinity) ||
            a === Infinity ||
            b === Infinity ||
            a * b < 0);
    }
    function ComputeGap(a, b) {
        const gap = Math.abs((a - b) / Math.min(Math.abs(a), Math.abs(b)));
        return Math.round(gap * 10000) / 100;
    }
    if (dir === "max") {
        [a, b] = [b, a];
    }
    if (AreValuesEffectivelyEqual(Number(a), Number(b), tol)) {
        return 0.0;
    }
    if (IsGapCalculationNotApplicable(Number(a), Number(b), tol)) {
        return Infinity;
    }
    return ComputeGap(Number(a), Number(b));
}
export function SetModelStatus(modelStatus) {
    const statusMap = {
        1: "Optimal",
        2: "Locally Optimal",
        3: "Unbounded",
        4: "Infeasible",
        5: "Locally Infeasible",
        6: "Intermediate Infeasible",
        7: "Feasible Solution",
        8: "Integer Solution",
        9: "Intermediate Non-integer",
        10: "Integer Infeasible",
        11: "Lic Problem - No Solution",
        12: "Error Unknown",
        13: "Error No Solution",
        14: "No Solution Returned",
        15: "Solved Unique",
        16: "Solved",
        17: "Solved Singular",
        18: "Unbounded - No Solution",
        19: "Infeasible - No Solution"
    };
    if (typeof modelStatus === "string") {
        modelStatus = parseInt(modelStatus);
    }
    return statusMap[modelStatus] || "Unknown Error";
}
export function SetSolverStatus(solverStatus) {
    const statusMap = {
        1: "Normal Completion",
        2: "Iteration Interrupt",
        3: "Resource Interrupt",
        4: "Terminated By Solver",
        5: "Evaluation Interrupt",
        6: "Capability Problems",
        7: "Licensing Problems",
        8: "User Interrupt",
        9: "Error Setup Failure",
        10: "Error Solver Failure",
        11: "Error Internal Solver Failure",
        12: "Solve Processing Skipped",
        13: "Error System Failure"
    };
    if (typeof solverStatus === "string") {
        solverStatus = parseInt(solverStatus);
    }
    return statusMap[solverStatus] || "Unknown Error";
}
export function CompareSolvers(solver1, solver2, solverTimes) {
    const results1 = solverTimes[solver1];
    const results2 = solverTimes[solver2];
    const comparisonSummary = {
        better: 0,
        worse: 0,
        equal: 0,
        details: []
    };
    results1.forEach((result1) => {
        const result2 = results2.find((r) => r.InputFileName === result1.InputFileName);
        if (result2) {
            if (result1.time < result2.time) {
                comparisonSummary.better++;
                comparisonSummary.details.push({
                    InputFileName: result1.InputFileName,
                    time1: result1.time,
                    time2: result2.time,
                    comparison: "better"
                });
            }
            else if (result1.time > result2.time) {
                comparisonSummary.worse++;
                comparisonSummary.details.push({
                    InputFileName: result1.InputFileName,
                    time1: result1.time,
                    time2: result2.time,
                    comparison: "worse"
                });
            }
            else {
                comparisonSummary.equal++;
                comparisonSummary.details.push({
                    InputFileName: result1.InputFileName,
                    time1: result1.time,
                    time2: result2.time,
                    comparison: "equal"
                });
            }
        }
    });
    return comparisonSummary;
}
export function ExtractUniqueProblems(traceData) {
    const unique = {};
    traceData.forEach((item) => {
        const fileName = item["InputFileName"];
        if (!unique[fileName]) {
            unique[fileName] = {
                InputFileName: fileName,
                Direction: item["Direction"],
                NumberOfEquations: item["NumberOfEquations"],
                NumberOfVariables: item["NumberOfVariables"],
                NumberOfDiscreteVariables: item["NumberOfDiscreteVariables"],
                NumberOfNonZeros: item["NumberOfNonZeros"],
                NumberOfNonlinearNonZeros: item["NumberOfNonlinearNonZeros"],
                PrimalBoundProblem: item["PrimalBoundProblem"],
                DualBoundProblem: item["DualBoundProblem"]
            };
        }
    });
    return Object.values(unique);
}
export function CalculateInstanceAttributes(data) {
    const results = {};
    const keys = Object.keys(data[0]).filter((key) => key !== "InputFileName");
    keys.forEach((key) => {
        const values = data
            .map((item) => Number(item[key]))
            .filter((value) => !isNaN(value));
        if (values.length > 0) {
            const avgValue = math.format(math.mean(values), { precision: 7 });
            const minValue = math.format(math.min(values), { precision: 7 });
            const maxValue = math.format(math.max(values), { precision: 7 });
            const stdValue = math.format(math.std(values), { precision: 7 });
            const p10Value = Number(math.format(math.quantileSeq(values, 0.1), { precision: 7 }));
            const p25Value = Number(math.format(math.quantileSeq(values, 0.25), { precision: 7 }));
            const p50Value = Number(math.format(math.quantileSeq(values, 0.5), { precision: 7 }));
            const p75Value = Number(math.format(math.quantileSeq(values, 0.75), { precision: 7 }));
            const p90Value = Number(math.format(math.quantileSeq(values, 0.9), { precision: 7 }));
            const countValue = values.length;
            results[key] = {
                countValue,
                avgValue: Number(avgValue),
                minValue: Number(minValue),
                maxValue: Number(maxValue),
                stdValue: Number(stdValue),
                p10Value: Number(p10Value),
                p25Value: Number(p25Value),
                p50Value: Number(p50Value),
                p75Value: Number(p75Value),
                p90Value: Number(p90Value)
            };
        }
    });
    return results;
}
export function CalculateSolveAttributes(data, specificKeys) {
    const results = {};
    specificKeys.forEach((key) => {
        const values = data
            .map((item) => parseFloat(String(item[key])))
            .filter((value) => !isNaN(value));
        if (values.length > 0) {
            results[key] = {
                countValue: values.length,
                avgValue: Number(math.format(math.mean(values), { precision: 7 })),
                minValue: Number(math.format(math.min(values), { precision: 7 })),
                maxValue: Number(math.format(math.max(values), { precision: 7 })),
                stdValue: Number(math.format(math.std(values), { precision: 7 })),
                p10Value: Number(math.format(math.quantileSeq(values, 0.1), { precision: 7 })),
                p25Value: Number(math.format(math.quantileSeq(values, 0.25), { precision: 7 })),
                p50Value: Number(math.format(math.quantileSeq(values, 0.5), { precision: 7 })),
                p75Value: Number(math.format(math.quantileSeq(values, 0.75), { precision: 7 })),
                p90Value: Number(math.format(math.quantileSeq(values, 0.9), { precision: 7 }))
            };
        }
    });
    return results;
}
function IsInfinite(value) {
    return value == Infinity || value == -Infinity;
}
function ExceedsBound(a, b) {
    function IsRelativeDifference(a, b, tol) {
        let relDiff;
        if (Math.abs(a) === Infinity || Math.abs(b) === Infinity) {
            relDiff = a === b ? 0.0 : a - b;
        }
        else {
            relDiff = (a - b) / Math.max(Math.abs(a), Math.abs(b), 1.0);
        }
        return relDiff > tol;
    }
    return (a - b > Values.ABSOLUTE_TOLERANCE &&
        IsRelativeDifference(a, b, Values.RELATIVE_TOLERANCE));
}
export function SetFailValueAndReason(terminationStatus, direction, primalBoundSolver, dualBoundSolver, primalBoundProblem, dualBoundProblem) {
    if (!terminationStatus) {
        return [true, "No data"];
    }
    if (terminationStatus === "Capability Problem" ||
        terminationStatus === "Unknown Error" ||
        terminationStatus === "User Interrupt" ||
        terminationStatus === "Error") {
        return [true, `Termstatus is ${terminationStatus}`];
    }
    const isMinimization = direction === "min";
    if (!IsInfinite(primalBoundSolver) && !IsInfinite(dualBoundProblem)) {
        const primal = Number(primalBoundSolver);
        const dual = Number(dualBoundProblem);
        const contradicts = isMinimization
            ? ExceedsBound(dual, primal)
            : ExceedsBound(primal, dual);
        if (contradicts) {
            return [true, "Primal bound contradicts best known dual bound"];
        }
    }
    if (!IsInfinite(dualBoundSolver) && !IsInfinite(primalBoundProblem)) {
        const dual = Number(dualBoundSolver);
        const primal = Number(primalBoundProblem);
        const contradicts = isMinimization
            ? ExceedsBound(dual, primal)
            : ExceedsBound(primal, dual);
        if (contradicts) {
            return [true, "Dual bound contradicts best known primal bound"];
        }
    }
    return [false, "Normal Completion"];
}
