import { ErrorMessages } from "../../Constants/Messages";
import { DisplayErrorNotification } from "./DisplayAlertNotification";
export function PopulateCheckboxes(traceData) {
    const container = document.getElementById("solverOptions");
    const uniqueSolvers = Array.from(new Set(traceData.map((solver) => solver["SolverName"]))).filter((solver) => solver !== undefined);
    if (container) {
        uniqueSolvers.forEach((solver) => {
            const checkbox = document.createElement("input");
            checkbox.type = "checkbox";
            checkbox.id = solver;
            checkbox.value = solver;
            checkbox.name = solver;
            checkbox.classList.add("form-check-input");
            const label = document.createElement("label");
            label.htmlFor = solver;
            label.appendChild(document.createTextNode(solver));
            label.classList.add("form-check-label");
            const div = document.createElement("div");
            div.classList.add("form-check");
            div.appendChild(checkbox);
            div.appendChild(label);
            container.appendChild(div);
        });
    }
    else {
        console.error("Container element not found.");
    }
    if (container) {
        EnforceCheckboxLimit(container, 2);
    }
    else {
        console.error("Container element not found.");
    }
}
function EnforceCheckboxLimit(container, maxLimit) {
    container.addEventListener("change", (event) => {
        const checkedCheckboxes = container.querySelectorAll('input[type="checkbox"]:checked');
        if (checkedCheckboxes.length > maxLimit) {
            event.target.checked = false;
            DisplayErrorNotification(ErrorMessages.SELECT_SOLVER_AMOUNT);
        }
    });
}
export function GetSelectedCheckboxValues() {
    const selectedValues = [];
    const checkboxes = document.querySelectorAll(`input[type="checkbox"]:checked`);
    checkboxes.forEach((checkbox) => {
        selectedValues.push(checkbox.value);
    });
    return selectedValues;
}
