import * as math from "mathjs";
import { Values } from "../../Constants/Values";
import { ComputeVirtualTimesTraceData } from "../ResultComputations/ComputeVirtualSolvers";
import { elements } from "../../Elements/Elements";
export function ComputeStatisticalMeasures(resultsData, category, defaultTime, filterType) {
    let data;
    if (filterType && filterType !== "None") {
        resultsData = FilterByType(filterType, resultsData);
    }
    if (category === "SolverTime") {
        if (!defaultTime) {
            defaultTime = Values.DEFAULT_TIME;
        }
        const virtualData = ComputeVirtualTimesTraceData(resultsData, defaultTime);
        data = [...resultsData, ...virtualData];
    }
    else {
        data = resultsData;
    }
    if (category !== "NumberOfNodes" &&
        category !== "NumberOfIterations" &&
        category !== "SolverTime") {
        data = data.filter((obj) => isFinite(Number(obj[category])));
    }
    const categoryValues = data.reduce((acc, curr) => {
        const parsedValue = Number(curr[category]);
        if (!isNaN(parsedValue)) {
            const solverName = curr["SolverName"];
            if (!acc[solverName]) {
                acc[solverName] = [];
            }
            acc[solverName].push(parsedValue);
        }
        return acc;
    }, {});
    const solverCategoryStats = {};
    for (const solverName in categoryValues) {
        if (Object.prototype.hasOwnProperty.call(categoryValues, solverName)) {
            const values = categoryValues[solverName];
            const avgValue = Number(math.format(math.mean(values), { precision: 7 }));
            const minValue = Number(math.format(math.min(values), { precision: 7 }));
            const maxValue = Number(math.format(math.max(values), { precision: 7 }));
            const stdValue = Number(math.format(math.std(values), { precision: 7 }));
            const sumValue = Number(math.format(math.sum(values), { precision: 7 }));
            const p10Value = Number(math.format(math.quantileSeq(values, 0.1), { precision: 7 }));
            const p25Value = Number(math.format(math.quantileSeq(values, 0.25), { precision: 7 }));
            const p50Value = Number(math.format(math.quantileSeq(values, 0.5), { precision: 7 }));
            const p75Value = Number(math.format(math.quantileSeq(values, 0.75), { precision: 7 }));
            const p90Value = Number(math.format(math.quantileSeq(values, 0.9), { precision: 7 }));
            solverCategoryStats[solverName] = {
                avgValue: avgValue,
                minValue: minValue,
                maxValue: maxValue,
                stdValue: stdValue,
                sumValue: sumValue,
                p10Value: p10Value,
                p25Value: p25Value,
                p50Value: p50Value,
                p75Value: p75Value,
                p90Value: p90Value
            };
        }
    }
    return solverCategoryStats;
}
function FilterByType(filterType, categoryValues) {
    switch (filterType) {
        case "no_fail_by_all_solver":
            return categoryValues.filter((obj) => obj["SolverStatus"] === "Normal Completion");
        case "time_greater_than_10_by_at_least_one_solver_and_no_fail":
            return categoryValues.filter((obj) => (obj["SolverTime"] ?? 0) <= 10 &&
                obj["SolverStatus"] === "Normal Completion");
        case "solver_primal_gap_less_than_or_equal_to_1_percent_and_no_fail":
            return categoryValues.filter((obj) => (obj["PrimalGap"] ?? 0) <= 1 &&
                obj["SolverStatus"] === "Normal Completion");
        case "solver_primal_gap_less_than_or_equal_to_10_percent_and_no_fail":
            return categoryValues.filter((obj) => (obj["PrimalGap"] ?? 0) <= 10 &&
                obj["SolverStatus"] === "Normal Completion");
        case "solver_dual_gap_less_than_or_equal_to_1_percent_and_not_failed":
            return categoryValues.filter((obj) => (obj["DualGap"] ?? 0) <= 1 &&
                obj["SolverStatus"] === "Normal Completion");
        case "solver_dual_gap_less_than_or_equal_to_10_percent_and_not_failed":
            return categoryValues.filter((obj) => (obj["DualGap"] ?? 0) <= 10 &&
                obj["SolverStatus"] === "Normal Completion");
        default:
            return categoryValues;
    }
}
export function ExtractStatusMessages(traceData, statusType) {
    const result = [];
    const nameErrorMap = new Map();
    traceData.forEach((obj) => {
        const existingEntry = nameErrorMap.get(obj["SolverName"]);
        const status = obj[statusType];
        if (existingEntry) {
            existingEntry[status] = (existingEntry[status] || 0) + 1;
        }
        else {
            const newEntry = {
                SolverName: obj["SolverName"],
                [status]: 1
            };
            nameErrorMap.set(obj["SolverName"], newEntry);
            result.push(newEntry);
        }
    });
    return result;
}
export function ExtractFailedCount(traceData) {
    const result = [];
    const nameErrorMap = new Map();
    traceData.forEach((obj) => {
        const existingEntry = nameErrorMap.get(obj["SolverName"]);
        if (existingEntry) {
            existingEntry["Failed"] = (existingEntry["Failed"] || 0) + 1;
        }
        else {
            const newEntry = {
                SolverName: obj["SolverName"],
                Failed: 1
            };
            nameErrorMap.set(obj["SolverName"], newEntry);
            result.push(newEntry);
        }
    });
    return result;
}
export function ExtractAllSolverTimes(traceData) {
    const result = traceData.reduce((acc, obj) => {
        const solverName = obj["SolverName"];
        if (!acc[solverName]) {
            acc[solverName] = [];
        }
        if (obj["SolverTime"] !== undefined &&
            obj["SolverTime"] !== "NA") {
            const time = Number(obj["SolverTime"]);
            if (!isNaN(time)) {
                const inputFileName = obj["InputFileName"];
                acc[solverName].push({ time, InputFileName: inputFileName });
            }
        }
        return acc;
    }, {});
    return result;
}
export function ExtractAllSolverTimesGapType(traceData, selectedGapType, defaultTime, gapLimit, terminationStatusSelector) {
    let defaultTimeFallback;
    let gapLimitToCompare;
    let terminationStatus;
    if (!gapLimit || gapLimit < 0) {
        gapLimitToCompare = 0.01;
        elements.gapLimitDirectInput.value = "0.01";
    }
    else {
        gapLimitToCompare = gapLimit;
    }
    if (!defaultTime || defaultTime < 0) {
        defaultTimeFallback = Values.DEFAULT_TIME;
        elements.defaultTimeDirectInput.value = Values.DEFAULT_TIME.toString();
    }
    else {
        defaultTimeFallback = defaultTime;
    }
    if (!terminationStatusSelector) {
        terminationStatus = undefined;
    }
    else {
        const statusMap = {
            "1": "Normal Completion",
            "2": "Iteration Interrupt",
            "3": "Resource Interrupt",
            "4": "Terminated By Solver",
            "5": "Evaluation Interrupt",
            "6": "Capability Problems",
            "7": "Licensing Problems",
            "8": "User Interrupt",
            "9": "Error Setup Failure",
            "10": "Error Solver Failure",
            "11": "Error Internal Solver Failure",
            "12": "Solve Processing Skipped",
            "13": "Error System Failure"
        };
        terminationStatus = statusMap[terminationStatusSelector];
    }
    const virtualData = ComputeVirtualTimesTraceData(traceData, defaultTimeFallback);
    const combinedData = [...traceData, ...virtualData];
    const filteredData = combinedData.reduce((acc, obj) => {
        const solverName = obj["SolverName"];
        if (!acc[solverName]) {
            acc[solverName] = [];
        }
        if (obj["SolverTime"] !== undefined && !isNaN(obj["SolverTime"])) {
            if (obj[selectedGapType] <=
                gapLimitToCompare &&
                obj["SolverStatus"] === terminationStatus) {
                acc[solverName].push({
                    time: Number(obj["SolverTime"]),
                    InputFileName: obj["InputFileName"]
                });
            }
            else if (obj[selectedGapType] <=
                gapLimitToCompare &&
                terminationStatus === undefined) {
                acc[solverName].push({
                    time: Number(obj["SolverTime"]),
                    InputFileName: obj["InputFileName"]
                });
            }
        }
        else {
            acc[solverName].push({
                time: defaultTimeFallback,
                InputFileName: obj["InputFileName"]
            });
        }
        return acc;
    }, {});
    const result = filteredData;
    return result;
}
