import $ from "jquery";
import { elements } from "./Elements";
export function TableLoadingAnimation() {
    const loader = document.createElement("div");
    loader.className = "loader";
    elements.loaderContainer.innerHTML = "";
    elements.loaderContainer.appendChild(loader);
    elements.loaderContainer.style.display = "flex";
}
export function BodyFadeLoadingAnimation() {
    $(function () {
        $("body > :not(nav)").css("opacity", "1");
        $("hr").css("opacity", "0.25");
    });
}
