import { elements } from "../Elements/Elements";
import { TraceHeaderMap } from "../Constants/TraceHeaders";
import "bootstrap/dist/css/bootstrap.min.css";
import Modal from "bootstrap/js/dist/modal";
import { Captions } from "../Constants/Messages";
import { CalculateInstanceAttributes, CalculateSolveAttributes, ExtractUniqueProblems } from "../DataProcessing/ResultComputations/ComputeResults";
function SortKeysByEnum(obj) {
    const enumKeys = Object.keys(TraceHeaderMap);
    const objKeys = Object.keys(obj);
    const sortedEnumKeys = objKeys
        .filter((key) => {
        return enumKeys.includes(key);
    })
        .sort((a, b) => {
        return enumKeys.indexOf(a) - enumKeys.indexOf(b);
    });
    const nonEnumKeys = objKeys
        .filter((key) => {
        return !enumKeys.includes(key);
    })
        .sort();
    return [...sortedEnumKeys, ...nonEnumKeys];
}
export function TraceTableData(traceData) {
    const dataTableDiv = elements.dataTable;
    dataTableDiv.innerHTML = "";
    const dataTableHeaders = document.createElement("thead");
    dataTableHeaders.classList.add("thead-dark");
    const headerRow = document.createElement("tr");
    const sortedKeys = SortKeysByEnum(traceData[0]);
    for (const key of sortedKeys) {
        const th = document.createElement("th");
        th.textContent = TraceHeaderMap[key] || key;
        headerRow.appendChild(th);
    }
    dataTableHeaders.appendChild(headerRow);
    const dataTableContent = document.createElement("tbody");
    for (const obj of traceData) {
        const resultRow = document.createElement("tr");
        const sortedKeys = SortKeysByEnum(obj);
        for (const key of sortedKeys) {
            const value = obj[key];
            const td = document.createElement("td");
            if (value !== null && value !== undefined && !Number.isNaN(value)) {
                td.textContent = value.toString();
            }
            else if (Number.isNaN(value)) {
                td.textContent = "NaN";
            }
            else {
                td.textContent = "-";
            }
            resultRow.appendChild(td);
        }
        dataTableContent.appendChild(resultRow);
    }
    const newDataTable = document.createElement("table");
    newDataTable.classList.add("table", "table-bordered", "table-sm");
    newDataTable.id = "dataTableGenerated";
    newDataTable.appendChild(dataTableHeaders);
    newDataTable.appendChild(dataTableContent);
    dataTableDiv.appendChild(newDataTable);
}
export function StatisticsTable(solverTimeStats, title) {
    elements.statisticsTableDiv.innerHTML = "";
    const statisticsTable = document.createElement("table");
    statisticsTable.id = "statisticsTable_inner";
    statisticsTable.classList.add("table", "table-bordered", "table-hover", "table-sm");
    const tableCaption = document.createElement("caption");
    tableCaption.textContent = title + " statistics.";
    statisticsTable.appendChild(tableCaption);
    const header = statisticsTable.createTHead();
    header.classList.add("table-light");
    const headerRow = header.insertRow();
    const headers = [
        "Solver",
        "Average",
        "Min",
        "Max",
        "Std. Dev",
        "Sum",
        "10th %",
        "25th %",
        "50th %",
        "75th %",
        "90th %"
    ];
    headers.forEach((headerText) => {
        const headerCell = document.createElement("th");
        headerCell.textContent = headerText;
        headerRow.appendChild(headerCell);
    });
    const tableBody = statisticsTable.createTBody();
    const dataKeys = Object.keys(solverTimeStats);
    dataKeys.forEach((dataKey) => {
        const row = tableBody.insertRow();
        const nameCell = row.insertCell();
        nameCell.textContent = dataKey;
        nameCell.style.fontWeight = "bold";
        const dataValues = Object.values(solverTimeStats[dataKey]);
        dataValues.forEach((dataValue) => {
            const cell = row.insertCell();
            cell.textContent = dataValue.toString();
        });
    });
    elements.statisticsTableDiv.appendChild(statisticsTable);
}
export function ComparisonSummaryTable(comparisonSummary, comparisonSummaryInverse, solver1Name, solver2Name) {
    if (!elements.comparisonTableDiv)
        return;
    elements.comparisonTableDiv.innerHTML = "";
    const comparisonTable = document.createElement("table");
    comparisonTable.classList.add("table", "table-bordered", "table-hover", "table-sm");
    const tableCaption = document.createElement("caption");
    tableCaption.textContent = Captions.COMPARISON_TABLE_CAPTION;
    comparisonTable.appendChild(tableCaption);
    const header = comparisonTable.createTHead();
    header.classList.add("table-light");
    const headerRow = header.insertRow();
    const headers = ["Comparison", solver1Name, solver2Name];
    headers.forEach((headerText) => {
        const headerCell = document.createElement("th");
        headerCell.textContent = headerText;
        headerRow.appendChild(headerCell);
    });
    const tableBody = comparisonTable.createTBody();
    const comparisons = ["Better", "Worse", "Equal"];
    comparisons.forEach((comparison) => {
        const row = document.createElement("tr");
        row.appendChild(CreateCell(comparison));
        let value1 = 0, value2 = 0;
        switch (comparison) {
            case "Better":
                value1 = comparisonSummary.better;
                value2 = comparisonSummaryInverse.better;
                break;
            case "Worse":
                value1 = comparisonSummary.worse;
                value2 = comparisonSummaryInverse.worse;
                break;
            case "Equal":
                value1 = comparisonSummary.equal;
                value2 = comparisonSummaryInverse.equal;
                break;
        }
        row.appendChild(CreateClickableCell(value1, comparison, comparisonSummary.details));
        row.appendChild(CreateClickableCell(value2, comparison, comparisonSummaryInverse.details));
        tableBody.appendChild(row);
    });
    elements.comparisonTableDiv.appendChild(comparisonTable);
}
function CreateCell(text) {
    const td = document.createElement("td");
    td.classList.add("fw-bold");
    td.textContent = text;
    return td;
}
function CreateClickableCell(value, comparisonType, details) {
    const td = document.createElement("td");
    switch (comparisonType) {
        case "Better":
            td.classList.add("table-success");
            break;
        case "Worse":
            td.classList.add("table-danger");
            break;
        case "Equal":
            td.classList.add("table-warning");
            break;
    }
    td.textContent = value.toString();
    td.style.cursor = "pointer";
    td.onclick = () => DisplayDetails(comparisonType, details);
    return td;
}
function DisplayDetails(comparisonType, details) {
    const filteredDetails = details.filter((detail) => detail.comparison === comparisonType.toLowerCase());
    if (elements.solverComparisonModalLabel)
        elements.solverComparisonModalLabel.innerHTML = `<i class="bi bi-clock-history"></i> ${Captions.COMPARSION_MODAL_LABEL} ${comparisonType}`;
    if (elements.solverComparisonModalBody) {
        elements.solverComparisonModalBody.innerHTML = "";
        const listGroup = document.createElement("ul");
        listGroup.className = "list-group";
        filteredDetails.forEach((detail) => {
            const listItem = document.createElement("li");
            listItem.className = "list-group-item";
            listItem.innerHTML = `${detail.InputFileName}, <b>${detail.time1}</b> compared to <b>${detail.time2}</b>`;
            listGroup.appendChild(listItem);
        });
        elements.solverComparisonModalBody.appendChild(listGroup);
    }
    const modal = new Modal(elements.solverComparisonModal, {
        keyboard: true
    });
    modal.show();
}
export function InstanceAttributesTable(traceData) {
    elements.instanceAttributesTableDiv.innerHTML = "";
    const instanceAttributesTable = document.createElement("table");
    instanceAttributesTable.id = "instanceAttributesTable_inner";
    instanceAttributesTable.classList.add("table", "table-bordered", "table-hover", "table-sm");
    const tableCaption = document.createElement("caption");
    tableCaption.textContent = Captions.INSTANCE_ATTRIBUTES_TABLE_CAPTION;
    instanceAttributesTable.appendChild(tableCaption);
    const uniqueData = ExtractUniqueProblems(traceData);
    const calculationResults = CalculateInstanceAttributes(uniqueData);
    const header = instanceAttributesTable.createTHead();
    header.classList.add("table-light");
    const headerRow = header.insertRow();
    const headers = [
        "Instance attribute",
        "Count",
        "Average",
        "Min",
        "Max",
        "Std. Dev",
        "10th %",
        "25th %",
        "50th %",
        "75th %",
        "90th %"
    ];
    headers.forEach((headerText) => {
        const headerCell = document.createElement("th");
        headerCell.textContent = headerText;
        headerRow.appendChild(headerCell);
    });
    const tableBody = instanceAttributesTable.createTBody();
    Object.entries(calculationResults).forEach(([key, values]) => {
        const row = tableBody.insertRow();
        const nameCell = row.insertCell();
        nameCell.textContent = key;
        nameCell.style.fontWeight = "bold";
        Object.entries(values).forEach(([_, value]) => {
            const cell = row.insertCell();
            cell.textContent = String(value);
        });
    });
    elements.instanceAttributesTableDiv.appendChild(instanceAttributesTable);
}
